package com.example.labux.data;

import com.example.labux.R;
import com.example.labux.model.Anime;

import java.util.ArrayList;
import java.util.List;

public class AnimeRepository {
    public static List<Anime> getAnimeList() {
        List<Anime> animeList = new ArrayList<>();
        animeList.add(new Anime("Attack on Titan", "Thriller, Drama, Action, Adventure, Horror, Comedy", "In a post-apocalyptic world where humanity is on the brink of extinction, the last remnants of civilization reside within enormous, concentric walls that protect them from terrifying giant humanoid creatures known as Titans. These monsters devour humans seemingly without reason, and no one truly knows where they came from. The story follows Eren Yeager, a young boy who witnesses the destruction of his hometown and the death of his mother during a Titan attack. Fueled by rage and a thirst for revenge, Eren joins the military alongside his childhood friends Mikasa Ackerman and Armin Arlert, swearing to wipe out every last Titan. However, as they rise through the ranks, they uncover horrifying truths about the Titans, the walls, and the origins of their world. \"Attack on Titan\" is a dark, emotionally intense anime that explores themes of freedom, fear, sacrifice, and the blurred lines between good and evil in times of war.", R.drawable.attack_on_titan));
        animeList.add(new Anime("Naruto", "Action, Adventure, Martial Arts, Super Power, Shounen", "In the Hidden Leaf Village, a boy named Naruto Uzumaki is shunned by the villagers for reasons he doesn’t understand. Unknown to him, he carries within his body the Nine-Tailed Fox Demon, a beast that once attacked the village and caused massive destruction. Despite being an outcast, Naruto is determined to gain the village’s respect by becoming Hokage, the strongest ninja and leader of the village. As Naruto grows up, he enrolls in the Ninja Academy and forms a team with Sasuke Uchiha, a talented but cold genius, and Sakura Haruno, whom he has a crush on. Under the guidance of their teacher Kakashi Hatake, they face difficult missions and dangerous enemies. Along the way, Naruto learns the value of hard work, friendship, perseverance, and the pain of loss. The series evolves into an epic saga about identity, legacy, peace, and the cycle of hatred, as Naruto fights not only to protect his friends and village but also to change the world for the better.", R.drawable.naruto));
        animeList.add(new Anime("Orb", "Historical, Drama, Psychological, Seinen", "Set in an alternate version of 15th-century Europe, Orb: On the Movements of the Earth follows a dark and thought-provoking story during a time when speaking scientific truths — such as the Earth revolving around the Sun — is considered heresy punishable by death. The anime centers around Rafal, a young boy with a brilliant mind and an insatiable curiosity. Living under the grip of a theocratic regime that suppresses knowledge, he becomes entangled in a secret movement of radical thinkers who risk their lives to uncover and share truths about the universe. What begins as a simple fascination with the stars becomes a dangerous journey of rebellion, philosophy, and martyrdom. With themes of free thought, oppression, science vs. religion, and the power of knowledge, Orb offers a haunting exploration of how far people will go to protect the truth — and how much they must sacrifice for it.", R.drawable.orb));
        animeList.add(new Anime("One Piece", "Action, Adventure, Comedy, Fantasy, Shounen, Super Power", "In a vast world covered mostly by ocean, where pirates roam in search of glory and riches, a legendary treasure known as One Piece lies hidden at the end of the Grand Line — the most dangerous and mysterious sea. Many have tried to claim it, but none have succeeded. Enter Monkey D. Luffy, a cheerful, carefree boy who gains the power of rubber after eating a cursed fruit known as the Gomu Gomu no Mi (Gum-Gum Fruit). Despite the danger, Luffy dreams of becoming the King of the Pirates by finding the One Piece and achieving absolute freedom. Along his journey, he gathers a diverse and loyal crew — including a swordsman, a navigator, a sniper, a cook, a doctor, an archaeologist, and more — each with their own dreams and tragic pasts. Together, the Straw Hat Pirates face powerful enemies, corrupt governments, ancient mysteries, and impossible odds. \"One Piece\" is an epic tale of friendship, adventure, laughter, and perseverance. It explores themes of justice, dreams, and the meaning of freedom in a world full of wonder and danger.", R.drawable.one_piece));
        animeList.add(new Anime("Tokyo Revenger", "Action, Supernatural, Delinquent, Drama, School, Shounen", "Takemichi Hanagaki is a 26-year-old man stuck in a dead-end life, working a part-time job and constantly plagued by regret. One day, he learns that his only girlfriend from middle school, Hinata Tachibana, and her younger brother have been killed by the ruthless Tokyo Manji Gang. Soon after, Takemichi is pushed in front of a train—but instead of dying, he wakes up 12 years in the past. Given a second chance, Takemichi realizes he can now change the future by altering the events of the past. He decides to infiltrate the Tokyo Manji Gang, rise through its ranks, and save Hinata and his friends from their tragic fate. Along the way, he uncovers complex relationships, gang politics, and the true nature of the people around him. \"Tokyo Revengers\" combines time travel with intense street gang drama, exploring themes of redemption, friendship, loyalty, and how one small decision can change everything. It’s an emotional rollercoaster filled with action, heartbreak, and determination.", R.drawable.tokyo_revengers));


        return animeList;
    }
}
